<?php require __DIR__.'/config/bootstrap.php';if(!setting('enable_registration','1'))exit('Registration disabled.');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']);$e=trim($_POST['email']);$pw=$_POST['password'];if(strlen($pw)<8||!filter_var($e,FILTER_VALIDATE_EMAIL))exit('Use a valid email and an 8+ character password.');try{$st=db()->prepare("INSERT INTO users(name,email,password_hash,role,status) VALUES(?,?,?,'user','active')");$st->execute([$name,$e,password_hash($pw,PASSWORD_DEFAULT)]);flash('success','Account created. Please login.');redirect('login.php');}catch(PDOException $x){flash('error','Email already registered.');}}$title='Register';require __DIR__.'/includes/header.php';?><h1>Create account</h1><form class="form" method="post"><?=csrf_field()?><label>Name</label><input name="name" required><label>Email</label><input name="email" type="email" required><label>Password</label><input name="password" type="password" minlength="8" required><button>Register</button></form><?php require __DIR__.'/includes/footer.php';?>